<script setup>import{Inbox}from'lucide-vue-next';defineProps({title:{type:String,default:'暂无内容'},description:String,actionLabel:String});defineEmits(['action'])</script><template><section class="empty" role="status"><Inbox/><h3>{{title}}</h3><p>{{description}}</p><button v-if="actionLabel" @click="$emit('action')">{{actionLabel}}</button><slot/></section></template><style scoped>.empty{min-height:170px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;color:var(--muted)}h3{font-size:14px;color:var(--text)}p{font-size:11px}button{padding:8px 12px;border:1px solid var(--line);border-radius:7px;background:var(--surface);color:var(--primary)}</style>